function minimumOneBitOperations(n) {
  // Follow the rules bit by bit from the top. Flipping bit i needs the bits below it to read 1 then zeros,
  // so toZero (clear bits 0..i) and toTop (make bits 0..i exactly 1 << i) call each other.
  const memo = new Map();
  const toZero = (x, i) => {
    if (i < 0) return 0;
    const key = `zero ${x} ${i}`;
    if (memo.has(key)) return memo.get(key);
    const top = 1 << i;
    const below = i > 0 ? 1 << (i - 1) : 0;
    const result = (x & top) === 0 ? toZero(x, i - 1) : toTop(x ^ top, i - 1) + 1 + toZero(below, i - 1);
    memo.set(key, result);
    return result;
  };
  const toTop = (x, i) => {
    if (i < 0) return 0;
    const key = `top ${x} ${i}`;
    if (memo.has(key)) return memo.get(key);
    const top = 1 << i;
    const below = i > 0 ? 1 << (i - 1) : 0;
    const result = (x & top) !== 0 ? toZero(x ^ top, i - 1) : toTop(x, i - 1) + 1 + toZero(below, i - 1);
    memo.set(key, result);
    return result;
  };
  return toZero(n, 29);
}

