function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const roll = rand();
  if (size === 'small') {
    if (roll < 0.15) return [1 << pick(11)];
    if (roll < 0.3) return [(1 << pick(11)) - 1];
    return [pick(1025)];
  }
  if (roll < 0.25) return [[1000000000, 536870912, 536870911, 999999999][pick(4)]];
  return [1 + pick(1000000000)];
}
